import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {pathToFileURL} from 'node:url';
const {Interpreter,RuntimeDiagnostics}=await import(pathToFileURL(process.argv[2]));
const source=readFileSync('/tmp/rank196-delivery/demos/euler/214_totientchains.ra','utf8')
.replace('40000000','100000').replace('arg Len integer = 25','arg Len integer = 15').replace('1000000','5000');
const runtime=new Interpreter(()=>{}, {compilation:!process.argv.includes('--reference')});
const diagnostics=new RuntimeDiagnostics();
try {const start=performance.now(); if(process.argv.includes('--diag')) diagnostics.run(()=>runtime.execute(source));else runtime.execute(source);
const ms=performance.now()-start;assert.equal(runtime.variables.get('Answer'),162726509n);
console.log(JSON.stringify({ms,rssMiB:process.resourceUsage().maxRSS/1024,answer:String(runtime.variables.get('Answer')),source,...(process.argv.includes('--diag')?{diagnostics}:{})}));}finally{runtime.dispose();}

