import {readFileSync,writeFileSync} from 'node:fs';
import assert from 'node:assert/strict';
import {Interpreter} from '/tmp/rank195-isolated/packages/interpreter/out/index.js';
const original=readFileSync('/tmp/rank196-delivery/demos/euler/211_divisorsquare.ra','utf8');
const reuse=original.replace('Total = 0','Total = 0\nSig = array shape Block fill 0').replace('  Sig = array shape Block fill 0','  for Clear in 0 till Block\n    Sig Clear = 0\n  end');
const mult=readFileSync('/tmp/rank211-multiplicative.ra','utf8');
const results=[];
for(const limit of [1,2,3,10,42,100,257,1000]) {
 let expected=0n;
 for(let n=1;n<limit;n++) {let s=0n;for(let d=1;d<=n;d++)if(n%d===0)s+=BigInt(d*d);let r=0n;while(r*r<s)r++;if(r*r===s)expected+=BigInt(n);}
 for(const block of [7,31]) for(const compilation of [false,true]) for(const [variant,text] of Object.entries({original,reuse,multiplicative:mult})) {
  const r=new Interpreter(()=>{}, {compilation});
  try {r.execute(text.replace('64000000',String(limit)).replace('1000000',String(block)));assert.equal(r.variables.get('Answer'),expected);results.push({limit,block,compilation,variant,answer:String(expected)});} finally {r.dispose();}
 }
}
writeFileSync('/tmp/rank211-verification.json',JSON.stringify(results,null,2));console.log(results.length+' independent checks pass');
